rows=[]
def add(label,out,accept,path,deps=(),low=30,high=60,lane='core',stage='Основа'):
 i=f'A{len(rows)+1:03d}'
 rows.append(dict(id=i,label=label,description=out,acceptance=accept,affected_files=[path],depends_on=list(deps),estimate_minutes={'minimum':low,'maximum':high},lane=lane,stage=stage))
 return i
