def call(command,*args):
 cp=subprocess.run([sys.executable,str(P/'plan_cli.py'),command,str(P),*args],capture_output=True,text=True)
 if cp.returncode: raise RuntimeError(cp.stdout+'\n'+cp.stderr)
 return cp.stdout
